import { Injectable } from '@angular/core';
import { HttpCallServieService } from '../../../services/http-call-servie.service';
import { setting } from '../../../setting';

@Injectable({
  providedIn: 'root',
})
export class CompanysubtypeService {
  constructor(private _HttpCallServieService_: HttpCallServieService) {}

  get() {
    var postData = {
      request_TYPE: 'GET',
      request_URI: setting.commonServicePath + 'companysubtype',
      request_BODY: '',
    };
    return this._HttpCallServieService_.api(postData);
  }

  getAll() {
    var postData = {
      request_TYPE: 'GET',
      request_URI: setting.commonServicePath + 'companysubtype/all',
      request_BODY: '',
    };
    return this._HttpCallServieService_.api(postData);
  }

  getOne(id) {
    var postData = {
      request_TYPE: 'GET',
      request_URI: setting.commonServicePath + 'companysubtype/' + id,
      request_BODY: '',
    };
    return this._HttpCallServieService_.api(postData);
  }

  add(data) {
    var postData = {
      request_TYPE: 'POST',
      request_URI: setting.commonServicePath + 'companysubtype',
      request_BODY: JSON.stringify(data),
    };
    return this._HttpCallServieService_.api(postData);
  }

  update(data, id) {
    var postData = {
      request_TYPE: 'PUT',
      request_URI: setting.commonServicePath + 'companysubtype/' + id,
      request_BODY: JSON.stringify(data),
    };
    return this._HttpCallServieService_.api(postData);
  }

  updateAll(data) {
    var postData = {
      request_TYPE: 'PUT',
      request_URI: setting.commonServicePath + 'companysubtype',
      request_BODY: JSON.stringify(data),
    };
    return this._HttpCallServieService_.api(postData);
  }

  delete(id) {
    var postData = {
      request_TYPE: 'DELETE',
      request_URI: setting.commonServicePath + 'companysubtype/' + id,
      request_BODY: '',
    };
    return this._HttpCallServieService_.api(postData);
  }

  search(data) {
    var postData = {
      request_TYPE: 'POST',
      request_URI: setting.commonServicePath + 'companysubtype/search',
      request_BODY: JSON.stringify(data),
    };
    return this._HttpCallServieService_.api(postData);
  }

  searchAll(data) {
    var postData = {
      request_TYPE: 'POST',
      request_URI: setting.commonServicePath + 'companysubtype/search/all',
      request_BODY: JSON.stringify(data),
    };
    return this._HttpCallServieService_.api(postData);
  }

  advancedSearch(data) {
    var postData = {
      request_TYPE: 'POST',
      request_URI: setting.commonServicePath + 'companysubtype/advancedsearch',
      request_BODY: JSON.stringify(data),
    };
    return this._HttpCallServieService_.api(postData);
  }

  advancedSearchAll(data) {
    var postData = {
      request_TYPE: 'POST',
      request_URI: setting.commonServicePath + 'companysubtype/advancedsearch/all',
      request_BODY: JSON.stringify(data),
    };
    return this._HttpCallServieService_.api(postData);
  }

  getAllDetail(response) {
    for (var a = 0; a < response.length; a++) {
      response[a] = this.getDetail(response[a]);
    }
    return response;
  }

  getDetail(response) {
    if (response.companytype_DETAIL != null) {
      response.companytype = JSON.parse(response.companytype_DETAIL);
      response.companytype_DETAIL =
        response.companytype.code + ' - ' + response.companytype.description;
    }
    return response;
  }
}
